import{_ as o,l as s,o as r,c as n,v as e,p as i,x as t,d as m,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"Transformer 块：注意力加前馈","description":"","frontmatter":{"title":"Transformer 块：注意力加前馈","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/transformer-block-compose.md","filePath":"llm/transformer-block-compose.md","lastUpdated":1789023840000}'),h={name:"llm/transformer-block-compose.md"};function F(A,a,E,f,c,u){const l=s("Mermaid");return r(),n("div",null,[a[1]||(a[1]=e('<h1 id="transformer-块-注意力加前馈" tabindex="-1">Transformer 块：注意力加前馈 <a class="header-anchor" href="#transformer-块-注意力加前馈" aria-label="Permalink to &quot;Transformer 块：注意力加前馈&quot;">​</a></h1><div class="epigraph"><p>编码器由 $N$ 个相同的层堆成；每一层有两个子层：多头自注意力，以及逐位置的全连接前馈网络，各自包在残差里。</p><footer>—— 据 Vaswani et al., Attention Is All You Need, NeurIPS 2017 整理</footer></div><p><a href="/llm/residual-stream">上一课</a>把通信协议写成 \\(x\\leftarrow x+F(x)\\)，并称这条 \\(x\\) 为残差流。本课不重讲为什么要残差、宽度为何等于 \\(d_{\\mathrm{model}}\\)。缺口是：\\(F\\) 是谁。一块 Transformer 里有两种不同的读写器——跨位置的注意力，与逐位置的前馈——各做一次残差加法，合起来叫做一个块。注意力的打分公式留给后面的 <a href="/llm/sdpa">SDPA</a>；本课只把块的组成钉死，并说明两种 \\(F\\) 在流上的分工。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/residual-stream">残差流</a>允许任何同宽的 \\(F\\) 往上写增量。若只有逐位置的多层感知机，位置之间不混合，序列任务做不成。若只有跨位置的混合、没有逐位置的非线性，每个位置只是在做彼此的线性组合，表达力停在「重排与加权」。Vaswani 等人给每一层配两种子层：先（或原则上）用注意力让位置互相读，再用前馈在每个位置上单独做一次宽的非线性。两件事不要挤进同一个 \\(F\\)，否则梯度与归纳偏置都缠在一起。</p><p>本课的问题因此是组合，不是内核。注意力内部如何缩放点积、如何分头、如何掩码，都还没发生。这里只需承认：存在一个从序列到序列、允许位置间通信的算子 \\(\\mathrm{Attn}\\)，以及一个按位置复制的算子 \\(\\mathrm{FFN}\\)。块是它们在残差流上的串联。</p><h3 id="两种-的定义域不同" tabindex="-1">两种 \\(F\\) 的定义域不同 <a class="header-anchor" href="#两种-的定义域不同" aria-label="Permalink to &quot;两种 $F$ 的定义域不同&quot;">​</a></h3><p>注意力的 \\(F\\) 在位置维上耦合：第 \\(i\\) 个输出依赖其他位置的当前流。前馈的 \\(F\\) 在位置维上对角：第 \\(i\\) 个输出只依赖位置 \\(i\\) 自己。这是块内最重要的不对称。后面谈信息路径、谈扩展比，都建立在这不对称上。不要把 FFN 想成「又一次注意力」；它看不见邻居。</p><p><span class="marginnote">串行块读的是加完注意力增量之后的流再进 FFN。并行块让两者读同一快照再把两个增量相加。本课默认 Vaswani 的串行组成；并行是后课的变体，不改变「有两种 \\(F\\)」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记块输入为 \\(x\\in\\mathbb{R}^{n\\times d}\\)。串行组成是</p> \\[x \\leftarrow x + \\mathrm{Attn}(x),\\qquad x \\leftarrow x + \\mathrm{FFN}(x). \\]<p>归一化省略不写，以免本课滑进 Pre-LN 争论。\\(\\mathrm{Attn}\\) 输出必须已是 \\(d\\) 维，以便加回流；\\(\\mathrm{FFN}\\) 同理。一个模型是 \\(N\\) 个这样的块堆叠。嵌入给出最初的 \\(x\\)；最后一层的流再进分类头——分类头与嵌入是否共享，上一单元已经讲过。</p><p>\\(\\mathrm{FFN}\\) 的内部宽度、激活函数，下一课才定量。本课只要求它是逐位置的：同一套参数应用到每个位置。\\(\\mathrm{Attn}\\) 的内部只要求它能让位置 \\(i\\) 读到（被允许的）位置 \\(j\\) 的信息。具体的相容性函数是 <a href="/llm/sdpa">SDPA</a> 的题目；多头是再后一课。读到「块」时，想到的应是「一次跨位置写增量，一次逐位置写增量」，而不是一张注意力热力图。</p><h3 id="块是重复的单位" tabindex="-1">块是重复的单位 <a class="header-anchor" href="#块是重复的单位" aria-label="Permalink to &quot;块是重复的单位&quot;">​</a></h3><p>参数不在块之间共享（标准做法）。每个块有自己的注意力投影与 FFN 矩阵，因而可以在不同深度上写不同类型的增量：浅层更靠近嵌入身份，深层更靠近预测方向。重复的是接口，不是权重。深度 \\(N\\) 增加的是读写次数，不是总线宽度——宽度在嵌入课已经定死。</p><p><span class="marginnote">「Transformer 层」与「Transformer 块」在本栏同义：都指注意力子层加前馈子层这一对。不要把单独的注意力子层叫一层，否则 \\(N=6\\) 会对不上原论文的计数。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>跨位置通信被限制在 \\(\\mathrm{Attn}\\) 里发生。FFN 再强，也只是把已经写在该位置上的流做一次高维非线性再投回来。于是「谁看见谁」完全由注意力的掩码与分数决定；「看见之后如何加工」有很大一部分发生在 FFN。这个分工让后面的解释可以分开问：失败是混合没发生，还是混合之后逐位置容量不够。扩展比课回答后一半；SDPA 课起回答前一半。</p><p>残差使两种增量都沉积在同一条流上。注意力写出的方向，FFN 可以读到并改写；FFN 写出的方向，下一块的注意力可以当成新的键值来读。块与块之间没有别的通道。这就是为什么流是中心对象：块只是规定了两种插件的调用顺序。</p><h3 id="为什么不是三次或一次子层" tabindex="-1">为什么不是三次或一次子层 <a class="header-anchor" href="#为什么不是三次或一次子层" aria-label="Permalink to &quot;为什么不是三次或一次子层&quot;">​</a></h3><p>一次子层：把非线性塞进注意力的值投影里，位置混合与位置内变换无法独立加宽。三次以上：例如再加一个跨位置卷积，历史上有人做过，主干不再默认。两次是最小的「混合 + 局部非线性」成对出现。解码器里若再加交叉注意力，那是第三种子层，定义域变成「读另一条序列」，属于后文交叉注意力课，不是本课的默认块。</p><p><span class="marginnote">本课不写 \\(QK^\\top\\)。看见注意力就想到缩放点积，会把块的组成问题偷换成内核问题。内核在模型架构课程的注意力课序里，从 SDPA 开始。</span></p>',23)),(r(),i(p,null,{default:t(()=>[d(l,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%9D%97%E8%BE%93%E5%85%A5%20x%20%E6%9D%A5%E8%87%AA%E5%B5%8C%E5%85%A5%E6%88%96%E4%B8%8A%E4%B8%80%E5%9D%97%22%5D%20--%3E%20A%5B%22x%20%E5%8A%A0%20Attn%20x%22%5D%0A%20%20A%20--%3E%20F%5B%22x%20%E5%8A%A0%20FFN%20x%22%5D%0A%20%20F%20--%3E%20Y%5B%22%E5%9D%97%E8%BE%93%E5%87%BA%EF%BC%8C%E5%AE%BD%E5%BA%A6%E4%BB%8D%E6%98%AF%20d%22%5D%0A%20%20ATT%5B%22%E8%B7%A8%E4%BD%8D%E7%BD%AE%E6%B7%B7%E5%90%88%22%5D%20--%3E%20A%0A%20%20FFN%5B%22%E9%80%90%E4%BD%8D%E7%BD%AE%E9%9D%9E%E7%BA%BF%E6%80%A7%22%5D%20--%3E%20F%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课的块是自注意力加 FFN。编码器-解码器的解码器块还要插入交叉注意力，接口仍是残差加法，但多一次读外源序列。仅解码器的语言模型把整网都建成「自注意力 + FFN」。MoE 把 FFN 换成路由到专家，仍是逐位置的那一种 \\(F\\)，不是第三种定义域。并行注意力-FFN、Sandwich 规范化，改顺序或改归一化，不改两种定义域。</p><p>组成钉死之后，下一课只补 FFN 中间有多宽；再下一课把一块之内张量怎么跳画成路径，作为「表示与 Transformer 块」课程的收束。注意力如何打分，从 <a href="/llm/sdpa">SDPA</a> 另起课序，不再从词表讲起。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一个 Transformer 块是残差流上的两种 \\(F\\)：跨位置的注意力，与逐位置的 FFN。</li><li>注意力公式本课不写，留给 <a href="/llm/sdpa">SDPA</a>；本课只定组成与分工。</li><li>FFN 看不见邻居；位置间信息只经注意力进入流。</li><li>块重复的是接口，每块有自己的权重；宽度 \\(d\\) 贯穿。</li><li>交叉注意力、MoE、并行块是定义域或顺序的变体，不是本课默认。</li><li>出处：Vaswani et al., NeurIPS 2017。</li></ul>',5))])}const x=o(h,[["render",F]]);export{_ as __pageData,x as default};
